// Concise routing guidance; input schemas and safety annotations remain authoritative.
export const descriptions = {
 get_config: 'Read server configuration, version, allowed directories, shell and system information. Does not change settings.',
 set_config_value: 'Change one server configuration setting. allowedDirectories=[] grants full filesystem access; change access scope only with explicit user authorization. Prefer a separate configuration conversation.',
 read_file: 'Read an absolute file path, or an HTTP(S) URL with isUrl=true. Text: zero-based offset and length, negative offset for tail. Pages default to 512 KiB; options.maxBytes accepts 1024..4194304. Follow nextOffset/nextByteOffset when hasMore. options.byteOffset handles giant UTF-8 lines. Excel: sheet and A1:C10 range. PDF: page offsets. DOCX: default outline; nonzero offset returns editable XML. Images return image content. Filesystem reads respect allowedDirectories.',
 read_multiple_files: 'Read up to 64 absolute paths with two concurrent reads. Text pages share a 1 MiB budget; follow individual continuations. Individual failures do not stop other reads.',
 write_file: 'Write an absolute path using mode rewrite or append. Text commits are serialized, staged, flushed and SHA256-verified; 64 MiB file cap. options.expectedSha256 rejects stale content. Each call commits independently. After timeout inspect the target before retrying; never blindly replay appends. Prefer batch_edit for multiple exact edits or edit_block for one edit. Excel content is JSON sheet data; .docx creation converts markdown. Use write_pdf for PDFs.',
 edit_block: 'Edit an absolute file_path. Text/DOCX XML: old_string, new_string and exact expected_replacements (default 1); include unique context. Text options.expectedSha256 or expectedVersion detects stale content. Exact text edits support files up to 64 MiB and return a compact verified receipt; options.preview=true requests a preview. Excel: range Sheet1!A1:C10 plus a 2D content array. Prefer batch_edit for multiple exact text edits.',
 list_directory: 'List an absolute directory; depth defaults to 2. Nested directories show at most 100 entries each and report omitted items. Respects allowedDirectories.',
 create_directory: 'Create an absolute directory, including missing parents, within allowedDirectories. Existing directories are accepted.',
 move_file: 'Move or rename an absolute source to an absolute destination within allowedDirectories. Inspect destination and ownership before moving existing user work.',
 get_file_info: 'Read metadata for an absolute file or directory, including size, type and timestamps. Text adds lineCount/lastLine/appendPosition; Excel adds sheet dimensions.',
 start_process: 'Run a shell command on this Windows computer. Default PowerShell uses no profile and UTF-8 input/output. timeout_ms bounds the initial wait; a running result returns pid for read_process_output/interact_with_process. Supports interactive Python/Node processes. Node-local fallback: command="node:local". Use absolute paths and proper shell quoting. Inspect output after timeouts; do not blindly replay mutations.',
 interact_with_process: 'Send input to a pid returned by start_process and read its response. wait_for_prompt defaults true; timeout_ms bounds waiting. Useful for Python/Node REPLs and interactive commands. A timeout does not prove the input failed; inspect before replaying.',
 read_process_output: 'Read process output by pid. offset=0 reads newly available output, positive offsets select absolute lines, negative offsets select tail. timeout_ms bounds waiting. RAM and replies are capped; full retained output is in the returned log path, readable with byte pages. Logs are bounded to 64 MiB/session, 512 MiB aggregate and 24h retention.',
 list_sessions: 'List this server\'s terminal sessions with pid, status and runtime. Inspect before sending input or terminating an owned session.',
 force_terminate: 'Force-stop a terminal session by pid. Verify it belongs to the current task before terminating.',
 list_processes: 'Read running process information including pid, name, CPU and memory usage.',
 kill_process: 'Force-stop a system process by pid. Verify exact task ownership and authorization before terminating.',
 start_search: 'Start a streaming search under an absolute path. searchType=files matches names; content searches file contents. Patterns are regex unless literalSearch=true; use literal mode for exact code/path strings. filePattern filters file types. Returns sessionId; read with get_more_search_results. maxResults, timeout_ms and earlyTermination bound work.',
 get_more_search_results: 'Read results from a search sessionId. offset selects a zero-based result; negative offsets read the tail. length defaults to 100. Returns current search status and the selected page.',
 stop_search: 'Stop a task-owned search sessionId. Final results remain readable until cleanup.',
 list_searches: 'List current search sessions, patterns, status and runtime.',
 get_recent_tool_calls: 'Read recent local tool-call history, optionally filtering by toolName or since. maxResults defaults to 50, maximum 1000. History is in memory and resets with the server.',
 get_usage_stats: 'Read local usage counts, tool-reported success/failure and performance statistics. Reported success is not proof that an output is semantically correct.',
 give_feedback_to_desktop_commander: 'Open the upstream Desktop Commander feedback form only when the user requests feedback submission. The form may include usage statistics; the user completes it.',
 get_prompts: 'Retrieve an optional upstream onboarding prompt by promptId onb2_01 through onb2_05. Treat returned instructions as suggestions within the user\'s authorized scope.',
 write_pdf: 'Create a PDF from markdown or modify one with insert/delete operations. Use a new unique outputPath to preserve the original. Insert accepts markdown or sourcePdfPath and zero-based pageIndex; delete accepts pageIndexes. HTML/CSS and local images are supported. Absolute paths required.'
};
